const config = $input.first().json;
const cities = config.cities.split(',').map(c => c.trim());
const apiKey = config.tavily_api_key;
const queries = [];

// --- ALL CITY EVENT TYPES across ALL cities ---

// 1. College & campus fests
for (const city of cities) {
  queries.push({ query: `upcoming college cultural fest fest ${city} 2025 2026 sponsorship stall open`, city, category: 'Cultural Fest', apiKey });
}

// 2. Hackathons & tech conferences
for (const city of cities) {
  queries.push({ query: `upcoming hackathon tech summit developer conference ${city} 2025 2026 register`, city, category: 'Hackathon', apiKey });
}

// 3. Music concerts & entertainment
for (const city of cities) {
  queries.push({ query: `upcoming music concert live show entertainment event ${city} 2025 2026 stall vendor`, city, category: 'Concert', apiKey });
}

// 4. Food festivals & culinary events
for (const city of cities) {
  queries.push({ query: `upcoming food festival street food expo culinary event ${city} 2025 2026 stall booking`, city, category: 'Food Fest', apiKey });
}

// 5. Trade expos & B2B exhibitions
for (const city of cities) {
  queries.push({ query: `upcoming trade expo B2B exhibition business fair SME ${city} 2025 2026 stall sponsor`, city, category: 'B2B Expo', apiKey });
}

// 6. Marathons, sports & fitness events
for (const city of cities) {
  queries.push({ query: `upcoming marathon run sports fitness event ${city} 2025 2026 sponsor vendor`, city, category: 'Sports', apiKey });
}

// 7. Startup & entrepreneurship summits
for (const city of cities) {
  queries.push({ query: `upcoming startup summit entrepreneur investor meetup ${city} 2025 2026 sponsor`, city, category: 'Startup Summit', apiKey });
}

// 8. Cultural & religious festivals
for (const city of cities) {
  queries.push({ query: `upcoming cultural festival religious fair mela celebration ${city} 2025 2026 stall`, city, category: 'Cultural Festival', apiKey });
}

// 9. Corporate & professional conferences
for (const city of cities) {
  queries.push({ query: `upcoming corporate conference professional summit industry event ${city} 2025 2026 sponsor`, city, category: 'Corporate Conference', apiKey });
}

// 10. Wedding & lifestyle expos
for (const city of cities) {
  queries.push({ query: `upcoming wedding expo bridal show lifestyle fair ${city} 2025 2026 vendor stall`, city, category: 'Wedding Expo', apiKey });
}

// 11. Platform-specific searches
queries.push({ query: 'site:unstop.com upcoming events cultural fest hackathon open registration India 2025 2026', city: 'multi', category: 'Platform-Unstop', apiKey });
queries.push({ query: 'site:lu.ma upcoming events India conference meetup 2025 2026', city: 'multi', category: 'Platform-Luma', apiKey });
queries.push({ query: 'site:insider.in upcoming events concerts festivals India 2025 2026', city: 'multi', category: 'Platform-Insider', apiKey });
queries.push({ query: 'site:eventbrite.com upcoming events India 2025 2026 stall sponsor', city: 'multi', category: 'Platform-Eventbrite', apiKey });

return queries.map(q => ({ json: q }));

const allItems = $input.all();
const snippets = [];
for (const item of allItems) {
  const results = item.json.results || item.json.organic_results || [];
  for (const r of results) {
    const content = (r.content || r.snippet || r.description || '').substring(0, 600);
    if (content.length > 80) snippets.push(`TITLE: ${r.title || 'Unknown'}\nURL: ${r.url || ''}\nSNIPPET: ${content}`);
  }
}
if (snippets.length === 0) return [{ json: { llm_prompt: 'NO_RESULTS', snippets_count: 0 } }];
return [{ json: { llm_prompt: snippets.join('\n\n---\n\n'), snippets_count: snippets.length } }];

const item = $input.first().json;
const raw = item.output || item.text || '';
let events = [];

if (raw === 'NO_RESULTS' || !raw) return [{ json: { qualified_events: [], qualified_count: 0, total_found: 0 } }];

try {
  let str = typeof raw === 'string' ? raw : JSON.stringify(raw);
  str = str.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const match = str.match(/\[[\s\S]*\]/);
  if (match) events = JSON.parse(match[0]);
  else if (str.startsWith('[')) events = JSON.parse(str);
} catch (e) { events = []; }

if (!Array.isArray(events)) events = [];

// Deduplicate by name+city
const seen = new Set();
const unique = events.filter(ev => {
  const key = `${(ev.name||'').toLowerCase().trim()}_${(ev.city||'').toLowerCase().trim()}`;
  if (seen.has(key)) return false;
  seen.add(key); return true;
});

const today = new Date();

// Score ALL events — NO filtering, all pass through
const allScored = unique.map(ev => {
  let opp = 0;
  const att = parseInt(ev.expected_attendance) || 0;
  if (att >= 5000) opp += 30;
  else if (att >= 2000) opp += 20;
  else if (att >= 500) opp += 10;
  else opp += 5;

  if (ev.start_date) {
    try {
      const days = (new Date(ev.start_date) - today) / 86400000;
      if (days > 0 && days <= 30) opp += 40;
      else if (days > 30 && days <= 90) opp += 30;
      else if (days > 90 && days <= 180) opp += 20;
      else if (days > 180) opp += 10;
      else opp -= 10;
    } catch(e) { opp += 10; }
  } else { opp += 10; }

  if (ev.organizer) opp += 10;
  if (ev.city) opp += 10;
  if (ev.source_url) opp += 5;
  const sme = parseInt(ev.sme_fit_score) || 0;
  opp += Math.round(sme * 0.15);

  let urgency = 'PIPELINE';
  if (ev.start_date) {
    try {
      const days = (new Date(ev.start_date) - today) / 86400000;
      if (days <= 30) urgency = 'HOT';
      else if (days <= 90) urgency = 'PRIME';
      else if (days <= 180) urgency = 'PIPELINE';
      else urgency = 'LONG_HORIZON';
    } catch(e) {}
  }

  return { ...ev, opportunity_score: opp, sme_fit_score: sme, urgency };
});

// Sort best-first — NO score filter, NO slice cap. ALL events pass through.
const qualified = allScored
  .sort((a, b) => (b.sme_fit_score + b.opportunity_score) - (a.sme_fit_score + a.opportunity_score));

return [{ json: { qualified_events: qualified, qualified_count: qualified.length, total_found: unique.length } }];

const data = $input.first().json;
const events = data.qualified_events || [];
if (events.length === 0) return [];
return events.map(ev => ({ json: ev }));

const ev = $input.first().json;
const att = ev.expected_attendance ? `${parseInt(ev.expected_attendance).toLocaleString()} expected attendees` : 'audience size not confirmed';
const dates = ev.start_date ? `dates: ${ev.start_date}${ev.end_date ? ' to ' + ev.end_date : ''}` : 'dates upcoming';
const parts = [
  `${ev.name} in ${ev.city || 'India'}`,
  att, `event type: ${ev.type || 'event'}`, dates,
  ev.organizer ? `Organizer: ${ev.organizer}` : null,
  ev.source_url ? `Source: ${ev.source_url}` : null,
  ev.raw_summary || null
].filter(Boolean);
return [{ json: { raw_event: parts.join(', '), event_name: ev.name, city: ev.city, opportunity_score: ev.opportunity_score, sme_fit_score: ev.sme_fit_score } }];
